source("pre.R")
s <- zutable(id = c(1L, 2L, 3L), st = data.frame(a = c(1L, NA, 3L), b = c("x", NA, "z")), st2 = data.frame(a = 7:9, b = c("p", "q", "r")), l = list(1:2, NULL, 3L), l2 = list(9L, 8L, 7L))
for (q in list(quote(s[select = .(c = case(id > 1L ~ st, .default = st2))]), quote(s[select = .(c = case(id > 1L ~ st))]), quote(s[select = .(c = ifelse(id > 1L, st, st2))]), quote(s[select = .(c = coalesce(st, st2))]), quote(s[select = .(c = coalesce(l, l2))]), quote(s[select = .(c = ifelse(id > 1L, l, l2))]), quote(s[select = .(c = case(id > 1L ~ l, .default = l2))]), quote(s[select = .(c = ifelse(id == 2L, NA, l))]))) {
  cat(deparse(q), "\n"); a <- tryCatch({r <- eval(q); schema(r); as.data.frame(r)}, error = function(e) paste("ERR", class(e)[1], conditionMessage(e))); b <- ref(tryCatch({r <- eval(q); schema(r); as.data.frame(r)}, error = function(e) paste("ERR", class(e)[1], conditionMessage(e)))); if (is.character(a)) cat("   ", a, "\n") else str(a$c); if (!identical(a, b)) { cat("  REF differs:\n"); if (is.character(b)) cat("   ", b, "\n") else str(b$c) } }
